"discipline": "Patologia",
"TEMA": "Patología de la pared abdominal",
"comment": "La hernia inguinal indirecta es de origen congénito: se produce por la persistencia del conducto peritoneovaginal, por el que el saco herniario ingresa por el orificio inguinal profundo y recorre el canal inguinal. <br>La debilidad adquirida del triángulo de Hesselbach es el mecanismo de la hernia directa. La hernia indirecta recorre el canal inguinal y no solo su pared posterior (la hernia directa es la que atraviesa la pared posterior). Su saco emerge lateral a los vasos epigástricos inferiores; la hernia directa lo hace medial a ellos.",
