"question": "Durante un siniestro de tránsito, un hombre de 56 años de edad se ha golpeado violentamente contra el volante de su camión. Al llegar al departamento de emergencia, se encuentra diaforético y se queja de dolor en el tórax. Su presión sanguínea es de $60/40$ mm Hg y su frecuencia respiratoria es de 42 respiraciones por minuto. Cuál de los siguientes puntos es el mejor para diferenciar un taponamiento cardiaco de un neumotórax a tensión, como la causa de su hipotensión?",
