"b. El patrón tumoral predominante “primario“ se clasifica de 1 a 5, y el patrón “secundario“ se clasifica de forma similar, multiplicandose números para obtener la puntuación o score de Gleason.",
"c. La puntuación más baja de Gleason es 6, que es un cáncer de alto grado. Una puntuación de Gleason de 7 es un cáncer de grado medio, y una puntuación de Gleason de 8, 9 o 10 es un cáncer de bajo grado.",
