"discipline": "AnatoP",
"TEMA": "Patología prostática",
"comment": "El sistema de gradación de Gleason evalúa la arquitectura glandular y su patrón de infiltración estromal a bajo aumento. Se asigna un grado (1 a 5) al patrón predominante y al segundo patrón más frecuente (o de mayor grado en biopsias) y ambos se suman (no se multiplican) para obtener el score (donde 6 es bajo grado y 8-10 es alto grado)."
